int main() {
    int n, m;
    cin >> n >> m;
    vector<string> g(n);
    for (auto &row : g) cin >> row;
    long long ans = 0;
    // Each orbit under the two mirror symmetries has at most four cells; make it uniform with the majority color.
    for (int i = 0; i < (n + 1) / 2; i++)
        for (int j = 0; j < (m + 1) / 2; j++) {
            pair<int, int> cells[4] = {{i, j}, {i, m - 1 - j}, {n - 1 - i, j}, {n - 1 - i, m - 1 - j}};
            sort(cells, cells + 4);
            int size = unique(cells, cells + 4) - cells, blacks = 0;
            for (int k = 0; k < size; k++) blacks += g[cells[k].first][cells[k].second] == 'B';
            ans += min(blacks, size - blacks);
        }
    cout << ans << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        String[] g = new String[n];
        for (int i = 0; i < n; i++) g[i] = next();
        long ans = 0;
        for (int i = 0; i < (n + 1) / 2; i++)
            for (int j = 0; j < (m + 1) / 2; j++) {
                int[][] cells = {{i, j}, {i, m - 1 - j}, {n - 1 - i, j}, {n - 1 - i, m - 1 - j}};
                int size = 0, blacks = 0;
                Set<Integer> seen = new HashSet<>();
                for (int[] c : cells)
                    if (seen.add(c[0] * m + c[1])) {
                        size++;
                        if (g[c[0]].charAt(c[1]) == 'B') blacks++;
                    }
                ans += Math.min(blacks, size - blacks);
            }
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	g := make([]string, n)
	for i := range g {
		g[i] = string(token())
	}
	ans := 0
	for i := 0; i < (n+1)/2; i++ {
		for j := 0; j < (m+1)/2; j++ {
			cells := [4][2]int{{i, j}, {i, m - 1 - j}, {n - 1 - i, j}, {n - 1 - i, m - 1 - j}}
			seen := map[[2]int]bool{}
			size, blacks := 0, 0
			for _, c := range cells {
				if !seen[c] {
					seen[c] = true
					size++
					if g[c[0]][c[1]] == 'B' {
						blacks++
					}
				}
			}
			ans += min(blacks, size-blacks)
		}
	}
	fmt.Println(ans)
}
